function getViewBoxForZone(zone, w, h) {
  let region;
  if (zone && zone.length === 2 && COUNTRY_BBOX[zone]) {
    const [bx, by, bw, bh] = COUNTRY_BBOX[zone];
    const pad = Math.max(bw, bh) * 0.4;
    region = { x: bx - pad, y: by - pad, w: bw + pad * 2, h: bh + pad * 2 };
  } else {
    region = ZOOM_REGIONS[zone] || ZOOM_REGIONS['world'];
  }
  const rx = Math.max(0, region.x), ry = Math.max(0, region.y);
  const rw = Math.min(1000 - rx, region.w), rh = Math.min(500 - ry, region.h);
  const outputAspect = w / h, regionAspect = rw / rh;
  let vbx, vby, vbw, vbh;
  if (regionAspect > outputAspect) {
    vbw = rw; vbh = rw / outputAspect; vbx = rx; vby = ry + (rh - vbh) / 2;
  } else {
    vbh = rh; vbw = rh * outputAspect; vby = ry; vbx = rx + (rw - vbw) / 2;
  }
  vbx = Math.max(0, vbx); vby = Math.max(0, vby);
  return `${Math.round(vbx)} ${Math.round(vby)} ${Math.round(vbw)} ${Math.round(vbh)}`;
}

// ── GeoJSON country highlight using sharp composite ───────────────────────────
// بندي كل دولة مستطيل ملون شفاف فوق الخريطة الحقيقية
function hexToRgb(hex) {
  const r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
  return { r, g, b };
}

// ── SVG frame generator ───────────────────────────────────────────────────────
export function generateSVGFrame({ baseSvg, highlights, style, viewBox, w, h, events = [], currentTime = 0, flagData = {} }) {
  const colors = STYLES[style] || STYLES.dark;
  const [vbx, vby, vbw, vbh] = viewBox.split(' ').map(Number);

  let cssRules = `path { fill: ${colors.land}; stroke: ${colors.border}; stroke-width: 0.4; }`;

  // Apply natural colors for classic/clean styles
  if (style === 'classic' || style === 'clean') {
    for (const [iso, natColor] of Object.entries(COUNTRY_NATURAL_COLORS)) {
      if (!highlights[iso]) { // only if not highlighted
        cssRules += `#${iso}, .${iso} { fill: ${natColor}; }`;
      }
    }
  }

  // Apply highlight colors (override natural colors)
  for (const [iso, color] of Object.entries(highlights)) {
    cssRules += `#${iso}, [class="${iso}"] { fill: ${color} !important; }`;
  }

  const pathMatches = baseSvg.match(/<path[\s\S]*?(?:\/>|<\/path>)/g) || [];
  const paths = pathMatches.join('\n');

  const labelScale = vbw / 2000;
  const baseFontSize = 14;
  const fontSize = Math.round(baseFontSize * labelScale);
  const minFont = Math.max(8, fontSize);
  // Country labels hidden — cleaner look
  let labelsHTML = '';

  // ── Render active events: flags + military units ──────────────────────────
  let overlaysHTML = '';
  let defsHTML = '';
  let extraCSS = '';

  for (const event of events) {
    if (currentTime < event.time || currentTime >= event.time + event.duration) continue;
    const progress = (currentTime - event.time) / event.duration;

    // ── Military invasion arrow + element ─────────────────────────────────
    if (event.military && event.fromCountry && event.toCountry) {
      const fromLabel = COUNTRY_LABELS[event.fromCountry];
      const toLabel = COUNTRY_LABELS[event.toCountry];
      if (fromLabel && toLabel) {
        const [fx, fy] = fromLabel, [tx, ty] = toLabel;
        const inView = fx >= vbx && fx <= vbx + vbw && fy >= vby && fy <= vby + vbh;
        if (inView) {
          const ap = Math.min(progress * 1.5, 0.85);
          const mx = fx + (tx - fx) * ap, my = fy + (ty - fy) * ap;
          const sw = Math.max(1, Math.round(vbw * 0.004));
          const dr = Math.max(2, Math.round(vbw * 0.008));
          const aid = `arr_${Math.round(currentTime * 10)}`;
          const elemColor = event.color || '#ff0000';
          const elemSize = Math.max(8, Math.round(vbw * 0.025));
          // Arrow line
          defsHTML += `<marker id="${aid}" markerWidth="6" markerHeight="6" refX="3" refY="3" orient="auto"><path d="M0,0 L0,6 L6,3 z" fill="${elemColor}"/></marker>`;
          overlaysHTML += `<line x1="${fx}" y1="${fy}" x2="${tx}" y2="${ty}" stroke="${elemColor}" stroke-width="${sw}" stroke-dasharray="${dr*3} ${dr}" opacity="0.6" marker-end="url(#${aid})"/>`;
          // Moving element
          const elemType = event.unitType === 'plane' ? 'plane' : event.unitType === 'ship' ? 'ship' : 'tank';
          const elemFn = ELEMENT_SVG_DEFS[elemType];
          if (elemFn) overlaysHTML += elemFn(mx, my, elemSize, elemColor);
        }
      }
    }

    // ── Alliance line ──────────────────────────────────────────────────────
    if (event.eventType === 'alliance' && event.fromCountry && event.toCountry) {
      const fl = COUNTRY_LABELS[event.fromCountry], tl = COUNTRY_LABELS[event.toCountry];
      if (fl && tl) {
        const [fx, fy] = fl, [tx, ty] = tl;
        const sw = Math.max(1, Math.round(vbw * 0.004));
        const gr = Math.max(3, Math.round(vbw * 0.01));
        const ac = event.color || '#1d4ed8';
        overlaysHTML += `<line x1="${fx}" y1="${fy}" x2="${tx}" y2="${ty}" stroke="${ac}" stroke-width="${sw*2}" opacity="0.2"/>`;
        overlaysHTML += `<line x1="${fx}" y1="${fy}" x2="${tx}" y2="${ty}" stroke="${ac}" stroke-width="${sw}" opacity="0.85"/>`;
        overlaysHTML += `<circle cx="${fx}" cy="${fy}" r="${gr}" fill="${ac}" opacity="0.9"/>`;
        overlaysHTML += `<circle cx="${tx}" cy="${ty}" r="${gr}" fill="${ac}" opacity="0.9"/>`;
      }
    }

    // ── Trade / Aid flowing element ────────────────────────────────────────
    if (['trade','aid','resources','economic'].includes(event.eventType) && event.fromCountry && event.toCountry) {
      const fl = COUNTRY_LABELS[event.fromCountry], tl = COUNTRY_LABELS[event.toCountry];
      if (fl && tl) {
        const [fx, fy] = fl, [tx, ty] = tl;
        const ap = (Math.sin(currentTime * 2.5) + 1) / 2;
        const mx = fx + (tx-fx)*ap, my = fy + (ty-fy)*ap;
        const sw = Math.max(1, Math.round(vbw * 0.003));
        const elemSize = Math.max(6, Math.round(vbw * 0.022));
        const tc = event.color || (event.eventType === 'trade' ? '#f59e0b' : '#15803d');
        overlaysHTML += `<line x1="${fx}" y1="${fy}" x2="${tx}" y2="${ty}" stroke="${tc}" stroke-width="${sw}" stroke-dasharray="${elemSize} ${elemSize*0.5}" opacity="0.55"/>`;
        const elemFn = ELEMENT_SVG_DEFS[['trade','economic'].includes(event.eventType) ? 'money' : 'shield'];
        if (elemFn) overlaysHTML += elemFn(mx, my, elemSize, tc);
      }
    }

    // ── Blockade / Sanction ring ───────────────────────────────────────────
    if (['blockade','sanction'].includes(event.eventType)) {
      for (const iso of (event.countries || [])) {
        const label = COUNTRY_LABELS[iso];
        if (!label) continue;
        const [cx, cy] = label;
        if (cx < vbx || cx > vbx+vbw || cy < vby || cy > vby+vbh) continue;
        const rr = Math.round(vbw * 0.02);
        const rc = event.color || '#6b21a8';
        overlaysHTML += `<circle cx="${cx}" cy="${cy}" r="${rr}" fill="none" stroke="${rc}" stroke-width="${Math.round(vbw*0.003)}" stroke-dasharray="${rr*0.5} ${rr*0.3}" opacity="0.85"/>`;
        overlaysHTML += `<circle cx="${cx}" cy="${cy}" r="${Math.round(rr*0.28)}" fill="${rc}" opacity="0.6"/>`;
      }
    }

    // Labels removed
  }

  return `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" viewBox="${viewBox}" width="${w}" height="${h}">
  <defs>
    <linearGradient id="oceanGrad" x1="0%" y1="0%" x2="0%" y2="100%">
      <stop offset="0%" style="stop-color:${style === 'dark' ? '#0d1b3e' : style === 'military' ? '#0a1a0a' : '#3a7abf'};stop-opacity:1" />
      <stop offset="100%" style="stop-color:${style === 'dark' ? '#1a2744' : style === 'military' ? '#0d220d' : '#4a90d9'};stop-opacity:1" />
    </linearGradient>
    ${defsHTML}
  </defs>
  <style>${cssRules}${extraCSS}</style>
  <rect width="1000" height="500" fill="url(#oceanGrad)"/>
  ${paths}
  ${labelsHTML}
  ${overlaysHTML}
</svg>`;
}

// ── Groq: parse timeline ────────────────────────────────────────────────────────
async function parseMapTimeline(script, idea, mode, language, durationSecs = 60) {
  const content = mode === 'script' ? script : (idea || script || '');

  const prompt = `You are an expert geographic documentary director and map animator. Create a cinematic animated map timeline.

STORY/IDEA: ${content}
TOTAL DURATION: ${durationSecs} seconds
LANGUAGE: ${language || 'en'}

OUTPUT FORMAT (JSON only, no markdown):
{
  "script": "voiceover narration text that takes exactly ${durationSecs} seconds to read aloud at normal pace",
  "events": [
    {
      "time": 0,
      "duration": 10,
      "countries": ["DE"],
      "addCountries": [],
      "removeCountries": [],
      "zoom": "europe",
      "color": "#cc0000",
      "flag": true,
      "entity": "nazi germany",
      "eventType": "invasion",
      "military": true,
      "unitType": "tank",
      "fromCountry": "DE",
      "toCountry": "FR"
    }
  ]
}

CRITICAL RULES:

1. DURATION: Total events MUST cover exactly ${durationSecs}s. Last event (time+duration)=${durationSecs}. Min ${Math.max(6, Math.floor(durationSecs / 12))} events.

2. HOOK: Event at time=0 must be dramatic — bold color, tight zoom on the key place. No slow intros.

3. AUDIO SYNC: Each event = one narration sentence. Map changes exactly when narrator changes topic.

4. EXPANSION: 
   - "countries" = all countries currently in this event's color
   - "addCountries" = newly conquered/joined countries (keep previous colors too)
   - "removeCountries" = liberated/lost countries (fade out)
   Example conquest: event1 {countries:["DE"],color:"#cc0000"}, event2 {addCountries:["FR","BE"],color:"#cc0000"}, event3 {removeCountries:["FR"],addCountries:["RU"]}

5. HISTORICAL EMPIRES: For ancient/historical stories, set entity= the empire name and flag=true.
   Available: "ottoman empire", "roman empire", "byzantine empire", "mongol empire", "british empire", "umayyad caliphate", "abbasid caliphate", "persian empire", "ancient egypt", "pharaonic egypt", "macedonian empire", "alexander the great", "mughal empire", "qing dynasty", "aztec empire", "inca empire", "mali empire", "safavid empire", "napoleon", "russian empire", "austro-hungarian empire", "holy roman empire", etc.
   The map will show those countries in the empire's historical color automatically.

6. WHAT-IF SCENARIOS: For "what if X invaded Y" stories — treat it as real history. Germany invades US = show military arrows + expansion of German color across US states.

7. EVENT TYPES (set "eventType" field):
   - "invasion" → military arrow + red expansion
   - "alliance" → blue line connecting countries  
   - "trade" → flowing yellow dots between countries (set fromCountry + toCountry)
   - "aid" → flowing green dots (set fromCountry + toCountry)
   - "resources" → flowing brown dots (set fromCountry + toCountry)
   - "economic" → flowing orange dots
   - "blockade" → purple ring around country
   - "sanction" → purple ring around country
   - "annexation" → purple expansion
   - "liberation" → green replacement of red
   - "revolution" → orange highlight
   - "diplomatic" → cyan connecting line
   - "expansion" → bold color spread

8. COLORS BY TYPE:
   Invasion/aggressor: "#cc0000" or "#e11d48"
   Allies/liberation: "#1d4ed8" or "#15803d"  
   Trade/resources: "#f59e0b" or "#92400e"
   Alliance: "#1d4ed8"
   Empire: "#7c3aed"
   Neutral: "#6b7280"
   Ancient civilizations: "#c8860a" or "#8B6914"

9. ZOOM: Follow the action. Transitioning between distant regions → zoom to "world" for 3s first.

10. NO REPETITION: Every event shows something NEW. Never identical countries + color twice in a row.

11. NO "label" FIELD ever.

Countries: 2-letter ISO codes. zoom options: world, europe, western-europe, eastern-europe, scandinavia, balkans, iberia, british-isles, middle-east, gulf, levant, arabian-peninsula, holy-land, asia, central-asia, east-asia, south-asia, southeast-asia, far-east, africa, north-africa, west-africa, east-africa, southern-africa, horn-of-africa, great-lakes, sub-saharan, sahara, americas, north-america, south-america, central-america, caribbean, southern-cone, oceania, egypt, egypt-sinai, nile-valley, mesopotamia, anatolia, caucasus, iran-plateau, arabian-desert, ancient-egypt, ancient-rome, ancient-greece, ancient-persia, byzantine, ottoman, mongolia-steppe, silk-road`;

  const res = await fetch('https://api.groq.com/openai/v1/chat/completions', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${process.env.GROQ_API_KEY}` },
    body: JSON.stringify({ model: 'llama-3.3-70b-versatile', messages: [{ role: 'user', content: prompt }], max_tokens: 4000, temperature: 0.2 }),
  });

  const data = await res.json();
  const text = data.choices?.[0]?.message?.content || '';
  const clean = text.replace(/```json|```/g, '').trim();

  try {
    return JSON.parse(clean);
  } catch {
    const match = clean.match(/\{[\s\S]*\}/);
    if (match) {
      try { return JSON.parse(match[0]); } catch {}
    }
    return { script: content, events: [] };
  }
}

function resolveAudioPath(uploadedAudioUrl) {
  if (!uploadedAudioUrl) return null;
  if (fs.existsSync(uploadedAudioUrl)) return uploadedAudioUrl;
  const basename = path.basename(uploadedAudioUrl);
  const candidate = path.join(process.cwd(), 'outputs', basename);
  if (fs.existsSync(candidate)) return candidate;
  const stripped = uploadedAudioUrl.startsWith('/') ? uploadedAudioUrl.slice(1) : uploadedAudioUrl;
  const candidate2 = path.join(process.cwd(), stripped);
  if (fs.existsSync(candidate2)) return candidate2;
  return null;
}

// ── Groq Whisper captions ─────────────────────────────────────────────────────
async function transcribeAudioForMap(audioPath, language = 'en') {
  try {
    const { default: FormData } = await import('form-data');
    const audioBuffer = fs.readFileSync(audioPath);
    const formData = new FormData();
    formData.append('file', audioBuffer, { filename: 'audio.mp3', contentType: 'audio/mpeg' });
    formData.append('model', 'whisper-large-v3-turbo');
    formData.append('response_format', 'verbose_json');
    formData.append('timestamp_granularities[]', 'word');
    formData.append('language', language); // ← بيقول لـ Whisper اللغة عشان يتعرف صح

    const res = await fetch('https://api.groq.com/openai/v1/audio/transcriptions', {
      method: 'POST',
      headers: { 'Authorization': 'Bearer ' + process.env.GROQ_API_KEY, ...formData.getHeaders() },
      body: formData,
    });
    if (!res.ok) return null;
    const data = await res.json();
    return data.words || null;
  } catch { return null; }
}

// ── Add real captions with ffmpeg drawtext ────────────────────────────────────
async function addMapCaptions(videoPath, audioPath, outputPath, style = 'dark', ratio, language = 'en') {
  const isArabic = language === 'ar';

  // Arabic needs a font that supports Arabic — try Noto fonts first
  let FONT_PATH;
  if (isArabic) {
    const candidates = [
      '/usr/share/fonts/truetype/noto/NotoNaskhArabic-Regular.ttf',
      '/usr/share/fonts/truetype/noto/NotoSansArabic-Regular.ttf',
      '/usr/share/fonts/opentype/noto/NotoNaskhArabic-Regular.otf',
      '/usr/share/fonts/truetype/arabic/NotoNaskhArabic-Regular.ttf',
      '/usr/share/fonts/truetype/freefont/FreeSans.ttf',
      '/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',
    ];
    FONT_PATH = candidates.find(f => { try { return fs.existsSync(f); } catch { return false; } })
      || '/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf';
  } else {
    FONT_PATH = process.platform === 'win32'
      ? 'C\\:/Windows/Fonts/arial.ttf'
      : '/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf';
  }

  // Pass language to Whisper so it transcribes correctly
  const words = await transcribeAudioForMap(audioPath, language);
  if (!words || words.length === 0) {
    fs.copyFileSync(videoPath, outputPath);
    return;
  }

  // Arabic: fewer words per chunk (shorter lines)
  const chunkSize = isArabic ? 3 : 4;
  const chunks = [];
  for (let i = 0; i < words.length; i += chunkSize) {
    const group = words.slice(i, i + chunkSize);
    const text = group.map(w => w.word
      .replace(/['"`:;\\<>{}|]/g, '')
      .replace(/'/g, "\\'")
      .trim()
    ).filter(Boolean).join(' ');
    if (text) chunks.push({ text, start: group[0].start, end: group[group.length-1].end });
  }

  if (!chunks.length) { fs.copyFileSync(videoPath, outputPath); return; }

  const yExpr = ratio === '9:16' || ratio === '1:1' ? 'h-text_h-80' : 'h-text_h-60';
  const filters = chunks.map(c =>
    `drawtext=fontfile='${FONT_PATH}':text='${c.text}':fontsize=30:fontcolor=white` +
    `:borderw=2:bordercolor=black:box=1:boxcolor=0x00000088:boxborderw=10` +
    `:x=(w-text_w)/2:y=${yExpr}:enable='between(t,${c.start.toFixed(3)},${c.end.toFixed(3)})'`
  );

  if (!filters.length) { fs.copyFileSync(videoPath, outputPath); return; }

  try {
    execSync(
      `ffmpeg -i "${videoPath}" -vf "${filters.join(',')}" ` +
      `-c:a copy -c:v libx264 -crf 18 -preset fast -pix_fmt yuv420p -movflags +faststart -y "${outputPath}"`,
      { stdio: 'pipe' }
    );
  } catch {
    fs.copyFileSync(videoPath, outputPath);
  }
}

// ── Add background music ──────────────────────────────────────────────────────
function addMusicToVideo(videoPath, outputPath) {
  const musicDir = path.join(process.cwd(), 'assets', 'music');
  if (!fs.existsSync(musicDir)) { fs.copyFileSync(videoPath, outputPath); return; }
  const files = fs.readdirSync(musicDir).filter(f => f.endsWith('.mp3') || f.endsWith('.wav'));
  if (!files.length) { fs.copyFileSync(videoPath, outputPath); return; }
  const musicFile = path.join(musicDir, files[Math.floor(Math.random() * files.length)]);
  try {
    execSync(
      `ffmpeg -i "${videoPath}" -i "${musicFile}" ` +
      `-filter_complex "[1:a]volume=0.08[music];[0:a][music]amix=inputs=2:duration=first[aout]" ` +
      `-map 0:v -map "[aout]" -c:v copy -c:a aac -b:a 192k -movflags +faststart -y "${outputPath}"`,
      { stdio: 'pipe' }
    );
  } catch { fs.copyFileSync(videoPath, outputPath); }
}


// ── Flag cache ─────────────────────────────────────────────────────────────────
const flagCache = new Map();

async function getFlagBase64(isoCode) {
  if (!isoCode || isoCode.length !== 2) return null;
  const key = isoCode.toLowerCase();
  if (flagCache.has(key)) return flagCache.get(key);

  try {
    const url = `https://flagcdn.com/w80/${key}.png`;
    const res = await fetch(url, { timeout: 5000 });
    if (!res.ok) { flagCache.set(key, null); return null; }
    const buf = await res.arrayBuffer();
    const b64 = Buffer.from(buf).toString('base64');
    const dataUri = `data:image/png;base64,${b64}`;
    flagCache.set(key, dataUri);
    return dataUri;
  } catch {
    flagCache.set(key, null);
    return null;
  }
}

async function preloadFlags(isoCodes) {
  const unique = [...new Set(isoCodes.filter(Boolean).map(c => c.toLowerCase()))];
  await Promise.all(unique.map(iso => getFlagBase64(iso)));
  console.log(`[MapVideo] Preloaded ${flagCache.size} flags`);
}

// ── Main render ────────────────────────────────────────────────────────────────
export async function renderMapVideo({ jobId, formData, jobDir, updateStatus }) {
  const { mode, idea, script, voice, duration, ratio, language, mapStyle, uploadedAudioUrl, captions, music } = formData;

  const FPS = 24;
  const TRANSITION_FRAMES = 12;
  const durationSecs = duration === '30s' ? 30 : duration === '1min' ? 60 : duration === '2min' ? 120 : duration === '3min' ? 180 : 300;
  const [w, h] = ratio === '16:9' ? [1280, 720] : ratio === '1:1' ? [720, 720] : [720, 1280]; // default 9:16

  updateStatus(jobId, { progress: 10, log: ['🧠 Parsing story with AI...'] });

  const timeline = await parseMapTimeline(script, idea, mode, language, durationSecs);
  updateStatus(jobId, { progress: 20, log: [`✅ Timeline — ${timeline.events?.length || 0} events`, '🎙️ Generating voiceover...'] });

  let audioPath = null;
  if (uploadedAudioUrl) {
    audioPath = resolveAudioPath(uploadedAudioUrl);
  } else {
    try {
      const fn = await generateVoiceover(timeline.script || idea || script, voice || 'male_american', 'education', 0, language || 'en');
      audioPath = path.join(process.cwd(), 'outputs', fn);
    } catch (e) {
      console.warn('[MapVideo] TTS failed:', e.message);
    }
  }

  updateStatus(jobId, { progress: 30, log: ['✅ Voiceover ready', '🗺️ Generating map frames...'] });

  let actualAudioDuration = durationSecs;
  if (audioPath && fs.existsSync(audioPath)) {
    try {
      const result = execSync(
        `ffprobe -v error -show_entries format=duration -of default=noprint_wrappers=1:nokey=1 "${audioPath}"`,
        { encoding: 'utf8' }
      ).trim();
      const parsed = parseFloat(result);
      if (parsed > 0) actualAudioDuration = parsed;
    } catch {}
  }

  const totalSecs = Math.ceil(actualAudioDuration);
  // Preload all country flags
  const allISOs = (timeline.events || []).flatMap(e => [...(e.countries||[]),...(e.addCountries||[])]);
  await preloadFlags(allISOs);

  updateStatus(jobId, { progress: 37, log: ['🖼️ Generating map frames...'] });

  const baseSvg = await getWorldSvg();
  const framesDir = path.join(jobDir, 'frames');
  fs.mkdirSync(framesDir, { recursive: true });

  // Build cumulative highlights — supports addCountries/removeCountries for expansion
  const buildHighlightsAtTime = (t) => {
    const h2 = {};
    // Process events in order up to current time
    const sortedEvents = [...(timeline.events || [])].sort((a, b) => a.time - b.time);
    for (const ev of sortedEvents) {
      if (ev.time > t) break;
      const isActive = t >= ev.time && t < ev.time + ev.duration;
      if (!isActive) continue;

      // Set base countries for this event
      for (const iso of (ev.countries || [])) {
        if (iso && iso.length === 2) h2[iso] = ev.color || '#e11d48';
      }
      // Add new countries (expansion) — keep existing colors too
      for (const iso of (ev.addCountries || [])) {
        if (iso && iso.length === 2) h2[iso] = ev.color || '#e11d48';
      }
      // Remove countries (liberation/retreat)
      for (const iso of (ev.removeCountries || [])) {
        delete h2[iso];
      }
    }
    return h2;
  };

  // Track cumulative state across time for persistent highlights
  const cumulativeHighlights = {};
  const getHighlightsAtTime = (t) => {
    const sortedEvents = [...(timeline.events || [])].sort((a, b) => a.time - b.time);
    const state = {};
    for (const ev of sortedEvents) {
      if (ev.time > t) break;
      // Set/replace countries
      for (const iso of (ev.countries || [])) {
        if (iso && iso.length === 2) state[iso] = ev.color || '#e11d48';
      }
      // Add (expand)
      for (const iso of (ev.addCountries || [])) {
        if (iso && iso.length === 2) state[iso] = ev.color || '#e11d48';
      }
      // Remove (retreat)
      for (const iso of (ev.removeCountries || [])) {
        delete state[iso];
      }
    }
    return state;
  };

  const getZoneAtTime = (t) => {
    for (const ev of (timeline.events || [])) {
      if (t >= ev.time && t < ev.time + ev.duration) return ev.zoom || 'world';
    }
    return 'world';
  };

  const interpolateColor = (hex1, hex2, t) => {
    const r1=parseInt(hex1.slice(1,3),16),g1=parseInt(hex1.slice(3,5),16),b1=parseInt(hex1.slice(5,7),16);
    const r2=parseInt(hex2.slice(1,3),16),g2=parseInt(hex2.slice(3,5),16),b2=parseInt(hex2.slice(5,7),16);
    const r=Math.round(r1+(r2-r1)*t),g=Math.round(g1+(g2-g1)*t),b=Math.round(b1+(b2-b1)*t);
    return '#'+[r,g,b].map(v=>v.toString(16).padStart(2,'0')).join('');
  };

  let prevHighlights = {};
  let prevViewBox = getViewBoxForZone('world', w, h);

  for (let sec = 0; sec <= totalSecs; sec++) {
    const t = Math.min(sec, durationSecs);
    const highlights = getHighlightsAtTime(t);
    const zone = getZoneAtTime(t);
    const viewBox = getViewBoxForZone(zone, w, h);
    const allKeys = [...new Set([...Object.keys(prevHighlights), ...Object.keys(highlights)])];
    const COLORS = STYLES[mapStyle] || STYLES.dark;

    for (let tf = 0; tf < TRANSITION_FRAMES; tf++) {
      const progress = tf / TRANSITION_FRAMES;
      const transHighlights = {};
      for (const iso of allKeys) {
        const from = prevHighlights[iso] || COLORS.land;
        const to = highlights[iso] || COLORS.land;
        if (from !== to) transHighlights[iso] = interpolateColor(from, to, progress);
        else if (highlights[iso]) transHighlights[iso] = highlights[iso];
      }

      const parseVB = (vb) => vb.split(' ').map(Number);
      const fromVB = parseVB(prevViewBox), toVB = parseVB(viewBox);
      const eased = progress < 0.5 ? 2 * progress * progress : 1 - Math.pow(-2 * progress + 2, 2) / 2;
      const curVB = fromVB.map((v, i) => Math.round(v + (toVB[i] - v) * eased));
      const curViewBox = curVB.join(' ');
      const currentTime = sec + progress;

      const frameNum = sec * TRANSITION_FRAMES + tf;
      const pngPath = path.join(framesDir, `frame_${String(frameNum).padStart(6, '0')}.png`);

      const svgContent = generateSVGFrame({
        baseSvg, highlights: transHighlights, style: mapStyle,
        viewBox: curViewBox, w, h,
        events: timeline.events || [],
        currentTime,
        flagData: Object.fromEntries(flagCache),
      });
      await sharp(Buffer.from(svgContent)).resize(w, h, { fit: 'fill' }).png().toFile(pngPath);
    }

    prevHighlights = { ...highlights };
    prevViewBox = viewBox;

    if (sec % 5 === 0) {
      const pct = 30 + Math.round((sec / totalSecs) * 45);
      updateStatus(jobId, { progress: pct, log: [`🖼️ Frames... ${sec}/${totalSecs}s`] });
    }
  }

  updateStatus(jobId, { progress: 75, log: ['✅ Frames done', '🎬 Assembling video...'] });

  const listPath = path.join(framesDir, 'frames.txt');
  let listContent = '';
  const totalFrameCount = (totalSecs + 1) * TRANSITION_FRAMES;
  for (let fi = 0; fi < totalFrameCount; fi++) {
    const pngPath = path.join(framesDir, `frame_${String(fi).padStart(6, '0')}.png`);
    if (fs.existsSync(pngPath)) {
      listContent += `file '${pngPath}'\nduration ${(1 / TRANSITION_FRAMES).toFixed(4)}\n`;
    }
  }
  fs.writeFileSync(listPath, listContent);

  const rawVideoPath = path.join(jobDir, 'raw.mp4');
  const outputPath = path.join(jobDir, 'output.mp4');

  // Step 1: Build raw video — trim to exact audio duration
  let ffmpegCmd = `ffmpeg -y -f concat -safe 0 -i "${listPath}"`;
  if (audioPath && fs.existsSync(audioPath)) {
    ffmpegCmd += ` -i "${audioPath}"`;
    ffmpegCmd += ` -c:v libx264 -pix_fmt yuv420p -crf 18 -preset fast -r ${FPS}`;
    ffmpegCmd += ` -map 0:v:0 -map 1:a:0 -c:a aac -b:a 192k`;
    ffmpegCmd += ` -t ${actualAudioDuration.toFixed(2)}`; // trim to exact audio duration
  } else {
    ffmpegCmd += ` -c:v libx264 -pix_fmt yuv420p -crf 18 -preset fast -r ${FPS}`;
  }
  ffmpegCmd += ` "${rawVideoPath}"`;
  await execAsync(ffmpegCmd);

  updateStatus(jobId, { progress: 88, log: ['✅ Video assembled', '🎵 Adding music & captions...'] });

  // Step 2: Add music
  let currentPath = rawVideoPath;
  if (music !== false) {
    const withMusicPath = path.join(jobDir, 'with_music.mp4');
    addMusicToVideo(currentPath, withMusicPath);
    if (fs.existsSync(withMusicPath) && fs.statSync(withMusicPath).size > 10000) {
      currentPath = withMusicPath;
    }
  }

  // Step 3: Add captions (Groq Whisper)
  if (captions !== false && audioPath && fs.existsSync(audioPath) && process.env.GROQ_API_KEY) {
    updateStatus(jobId, { progress: 92, log: ['🗣️ Generating real captions with Whisper...'] });
    const withCaptionsPath = path.join(jobDir, 'with_captions.mp4');
    await addMapCaptions(currentPath, audioPath, withCaptionsPath, mapStyle, ratio, language || 'en');
    if (fs.existsSync(withCaptionsPath) && fs.statSync(withCaptionsPath).size > 10000) {
      currentPath = withCaptionsPath;
    }
  }

  // Step 4: Final copy
  try {
    execSync(`ffmpeg -i "${currentPath}" -c copy -movflags +faststart -y "${outputPath}"`, { stdio: 'pipe' });
  } catch {
    fs.copyFileSync(currentPath, outputPath);
  }

  updateStatus(jobId, { progress: 98, log: ['🎉 Done!'] });
  return outputPath;
}